/**
 * Resolve any country name (including multi-country strings like "Israel / Jordan" or "United States / Canada")
 * to its continental GeoZone ("asia" | "europe" | "americas" | "africa" | "oceania").
 */
export function getZoneForCountry(country: string): GeoZone {
  if (!country) return "europe";
  const primary = (country.split("/")[0] ?? country).trim().toLowerCase();
  return COUNTRY_TO_ZONE[primary] ?? "europe";
}

/**
 * Return a human-readable geographic subregion (e.g., "Western Europe", "South America", "Southeast Asia")
 * for SmartClue and the Lust Sin card.
 */
export function getSubregionForCountry(country: string): string {
  if (!country) return "World";
  const primary = (country.split("/")[0] ?? country).trim().toLowerCase();
  if (COUNTRY_TO_SUBREGION[primary]) return COUNTRY_TO_SUBREGION[primary]!;
  const zone = getZoneForCountry(country);
  const labels: Record<GeoZone, string> = {
    europe: "Europe",
    asia: "Asia",
    americas: "Americas",
    africa: "Africa",
    oceania: "Oceania",
  };
  return labels[zone];
}

