export const CITY_AND_COUNTRY_LOCATIONS: Location[] = cityAndCountryRows.map(
  ([name, country, lat, lng, category, difficulty, hint], i) => ({
    id: `wikidata-${category}-${i}`,
    name,
    country,
    lat,
    lng,
    category,
    difficulty,
    hint,
  }),
);

/**
 * Combined 10,500+ location dataset:
 * - STADIUM_LOCATIONS (Football Stadiums & Sports Arenas)
 * - WONDER_AND_ATTRACTION_LOCATIONS (World Wonders, UNESCO Sites, Tourist Attractions, Mountains & Natural Wonders)
 * - CITY_AND_COUNTRY_LOCATIONS (9,600+ World Cities, Capitals & Countries)
 */
export const WIKIDATA_LOCATIONS: Location[] = [
  ...STADIUM_LOCATIONS,
  ...WONDER_AND_ATTRACTION_LOCATIONS,
  ...CITY_AND_COUNTRY_LOCATIONS,
];

/** Major countries with rich multi-city pools ideal for "Find the City" mode. */
