/** Return all city & capital locations for a given country across WIKIDATA_LOCATIONS (and optional extra list). */
export function getCitiesForCountry(country: string, baseLocations: Location[] = []): Location[] {
  const target = country.trim().toLowerCase();
  const combined = [...baseLocations, ...CITY_AND_COUNTRY_LOCATIONS];
  const seen = new Set<string>();
  const result: Location[] = [];
  for (const loc of combined) {
    if (loc.category !== "city" && loc.category !== "capital") continue;
    if (loc.country.trim().toLowerCase() !== target) continue;
    const key = loc.name.trim().toLowerCase();
    if (seen.has(key)) continue;
    seen.add(key);
    result.push(loc);
  }
  return result;
}
